class MockPurplefishServer:
    """Mock server for Purplefish API endpoints"""

    def __init__(self, host: str = "127.0.0.1", port: int = 8000):
        self.host = host
        self.port = port
        self.server: Optional[HTTPServer] = None
        self.engagement_counter = 1000
        self.engagements: Dict[str, Dict[str, Any]] = {}

    def setup_routes(self) -> None:
        """Define all Purplefish API mock endpoints"""
        if not self.server:
            return

        # Create engagement endpoint
        self.server.expect_request(
            "/api/engagements", method="POST"
        ).respond_with_handler(self._handle_create_engagement)

        # Get agent config endpoint
        self.server.expect_ordered_request(
            "/api/engagements", method="GET"
        ).respond_with_handler(self._handle_get_agent_config)

        # Post candidate data points endpoint
        self.server.expect_ordered_request(
            "/api/engagements", method="POST"
        ).respond_with_handler(self._handle_post_data_point)

        # Post messages endpoint
        self.server.expect_ordered_request(
            "/api/engagements", method="POST"
        ).respond_with_handler(self._handle_post_message)

        # Health check endpoint
        self.server.expect_request("/health").respond_with_json(
            {"status": "ok", "service": "mock-purplefish-api"}
        )

    def _handle_create_engagement(self, request) -> Response:
        """Handle POST /api/engagements - Create engagement"""
        try:
            data = json.loads(request.data)
            room_name = data.get("roomName")
            opportunity_id = data.get("opportunityId")
            candidate_phone = data.get("candidatePhoneNumber")

            # Generate engagement ID
            engagement_id = f"eng_{self.engagement_counter}"
            self.engagement_counter += 1

            # Determine agent based on input
            if opportunity_id and opportunity_id.startswith("test_"):
                # For testing, use opportunity_id to determine agent type
                if "routing" in opportunity_id:
                    agent_name = "routing_agent"
                elif "voice" in opportunity_id:
                    agent_name = "voice_agent"
                else:
                    agent_name = "screening_agent"
            else:
                # Default agent selection logic
                agent_name = "screening_agent"

            # Store engagement data
            self.engagements[engagement_id] = {
                "id": engagement_id,
                "roomName": room_name,
                "opportunityId": opportunity_id,
                "candidatePhoneNumber": candidate_phone,
                "agentName": agent_name,
                "messages": [],
                "dataPoints": [],
            }

            # Return response in camelCase (as real API does)
            return Response(
                json.dumps({"engagementId": engagement_id, "agentName": agent_name}),
                status=200,
                headers={"Content-Type": "application/json"},
            )
        except Exception as e:
            return Response(
                json.dumps({"error": str(e)}),
                status=400,
                headers={"Content-Type": "application/json"},
            )

    def _handle_get_agent_config(self, request) -> Response:
        """Handle GET /api/engagements/{id}/agent-config"""
        path_parts = request.path.split("/")
        if len(path_parts) >= 4 and path_parts[-1] == "agent-config":
            engagement_id = path_parts[-2]

            if engagement_id in self.engagements:
                # Return a sample call script configuration
                config = {
                    "id": "mock_script_001",
                    "callScriptSchemaVersion": "1.0",
                    "callScriptVersion": "1.0",
                    "candidateDataPointSchemas": {
                        "issue_type": {
                            "key": "issue_type",
                            "description": "Type of technical issue",
                            "outputSchema": {
                                "type": "string",
                                "description": "Type of technical issue",
                            },
                        }
                    },
                    "context": {
                        "job": {
                            "companyName": "Mock Company",
                            "positionTitle": "Mock Position",
                        }
                    },
                    "tasks": [
                        {
                            "id": "greeter_task",
                            "type": "greeter",
                            "configuration": {
                                "companyName": "Mock Company",
                                "introduction": "Hello! This is a test call.",
                            },
                        },
                        {
                            "id": "closer_task",
                            "type": "closer",
                            "configuration": {"closingMessage": "Thank you for your time!"},
                        },
                    ],
                }
                return Response(
                    json.dumps(config),
                    status=200,
                    headers={"Content-Type": "application/json"},
                )
            else:
                return Response(
                    json.dumps({"error": "Engagement not found"}),
                    status=404,
                    headers={"Content-Type": "application/json"},
                )

        return Response(
            json.dumps({"error": "Invalid path"}),
            status=400,
            headers={"Content-Type": "application/json"},
        )

    def _handle_post_data_point(self, request) -> Response:
        """Handle POST /api/engagements/{id}/candidate-data-points"""
        path_parts = request.path.split("/")
        if len(path_parts) >= 4 and path_parts[-1] == "candidate-data-points":
            engagement_id = path_parts[-2]

            if engagement_id in self.engagements:
                try:
                    data = json.loads(request.data)
                    self.engagements[engagement_id]["dataPoints"].append(data)
                    return Response(
                        json.dumps({"success": True}),
                        status=200,
                        headers={"Content-Type": "application/json"},
                    )
                except Exception as e:
                    return Response(
                        json.dumps({"error": str(e)}),
                        status=400,
                        headers={"Content-Type": "application/json"},
                    )
            else:
                return Response(
                    json.dumps({"error": "Engagement not found"}),
                    status=404,
                    headers={"Content-Type": "application/json"},
                )

        return Response(
            json.dumps({"error": "Invalid path"}),
            status=400,
            headers={"Content-Type": "application/json"},
        )

    def _handle_post_message(self, request) -> Response:
        """Handle POST /api/engagements/{id}/messages"""
        path_parts = request.path.split("/")
        if len(path_parts) >= 4 and path_parts[-1] == "messages":
            engagement_id = path_parts[-2]

            if engagement_id in self.engagements:
                try:
                    data = json.loads(request.data)
                    self.engagements[engagement_id]["messages"].append(data)
                    return Response(
                        json.dumps({"success": True}),
                        status=200,
                        headers={"Content-Type": "application/json"},
                    )
                except Exception as e:
                    return Response(
                        json.dumps({"error": str(e)}),
                        status=400,
                        headers={"Content-Type": "application/json"},
                    )
            else:
                return Response(
                    json.dumps({"error": "Engagement not found"}),
                    status=404,
                    headers={"Content-Type": "application/json"},
                )

        return Response(
            json.dumps({"error": "Invalid path"}),
            status=400,
            headers={"Content-Type": "application/json"},
        )

    def start(self) -> HTTPServer:
        """Start the server in a background thread (for development use)"""
        self.server = HTTPServer(host=self.host, port=self.port)
        self.setup_routes()

        def run_server():
            self.server.start()

        thread = threading.Thread(target=run_server)
        thread.daemon = True
        thread.start()

        # Wait for server to be ready
        time.sleep(0.5)
        print(f"Mock Purplefish server started at http://{self.host}:{self.port}")
        return self.server

    def stop(self) -> None:
        """Stop the server"""
        if self.server:
            self.server.stop()
            print("Mock Purplefish server stopped")

    def get_url(self, path: str = "") -> str:
        """Get full URL for a path"""
        return f"http://{self.host}:{self.port}{path}"

    def reset(self) -> None:
        """Reset server state (useful between tests)"""
        self.engagement_counter = 1000
        self.engagements = {}


# For development - run this file directly
if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description="Mock Purplefish API Server")
    parser.add_argument(
        "--host", default="127.0.0.1", help="Host to bind to (default: 127.0.0.1)"
    )
    parser.add_argument(
        "--port", type=int, default=8000, help="Port to bind to (default: 8000)"
    )
    args = parser.parse_args()

    server = MockPurplefishServer(host=args.host, port=args.port)

    try:
        server.start()
        print(f"Server running at http://{args.host}:{args.port}")
        print("Available endpoints:")
        print("  POST /api/engagements - Create engagement")
        print("  GET  /api/engagements/{id}/agent-config - Get agent config")
        print("  POST /api/engagements/{id}/candidate-data-points - Post data point")
        print("  POST /api/engagements/{id}/messages - Post message")
        print("  GET  /health - Health check")
        print("\nPress Ctrl+C to stop...")

        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nShutting down...")
        server.stop()

