#!/usr/bin/env python3
"""
Standalone Mock Purplefish API Server for development and manual testing

Usage:
    python scripts/mock_purplefish_server.py
    python scripts/mock_purplefish_server.py --port 9000
    python scripts/mock_purplefish_server.py --host 0.0.0.0 --port 8080
"""

import argparse
import json
import logging
import time
from datetime import datetime
from http.server import BaseHTTPRequestHandler
from http.server import HTTPServer
from typing import Any
from typing import Dict
from urllib.parse import urlparse


logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class MockPurplefishHandler(BaseHTTPRequestHandler):
    """HTTP request handler for mock Purplefish API"""

    # Class-level state (shared across requests)
    engagement_counter = 1000
    engagements: Dict[str, Dict[str, Any]] = {}

    def do_POST(self):
        """Handle POST requests"""
        path = urlparse(self.path).path

        if path == "/api/engagements":
            self._handle_create_engagement()
        elif "/api/engagements/" in path and path.endswith("/candidate-data-points"):
            self._handle_post_data_point()
        elif "/api/engagements/" in path and path.endswith("/messages"):
            self._handle_post_message()
        else:
            self._send_error(404, "Not Found")

    def do_GET(self):
        """Handle GET requests"""
        path = urlparse(self.path).path

        if path == "/health":
            self._handle_health_check()
        elif "/api/engagements/" in path and path.endswith("/agent-config"):
            self._handle_get_agent_config()
        else:
            self._send_error(404, "Not Found")

    def _handle_create_engagement(self):
        """Handle POST /api/engagements"""
        try:
            content_length = int(self.headers['Content-Length'])
            post_data = self.rfile.read(content_length)
            data = json.loads(post_data)

            # Generate engagement ID
            engagement_id = f"eng_{MockPurplefishHandler.engagement_counter}"
            MockPurplefishHandler.engagement_counter += 1

            # Determine agent based on input
            opportunity_id = data.get("opportunityId")
            if opportunity_id and "routing" in opportunity_id:
                agent_name = "routing_agent"
            else:
                agent_name = "screening_agent"

            # Store engagement
            MockPurplefishHandler.engagements[engagement_id] = {
                "id": engagement_id,
                "roomName": data.get("roomName"),
                "opportunityId": opportunity_id,
                "candidatePhoneNumber": data.get("candidatePhoneNumber"),
                "agentPhoneNumber": data.get("agentPhoneNumber"),
                "agentName": agent_name,
                "messages": [],
                "dataPoints": [],
                "createdAt": datetime.now().isoformat(),
            }

            logger.info(f"Created engagement: {engagement_id} with agent: {agent_name}")

            # Send response
            response = {"engagementId": engagement_id, "agentName": agent_name}
            self._send_json_response(200, response)

        except Exception as e:
            logger.error(f"Error creating engagement: {e}")
            self._send_error(400, str(e))

    def _handle_get_agent_config(self):
        """Handle GET /api/engagements/{id}/agent-config"""
        path_parts = self.path.split("/")
        if len(path_parts) >= 4:
            engagement_id = path_parts[-2]

            if engagement_id in MockPurplefishHandler.engagements:
                config = {
                    "id": "mock_script_001",
                    "callScriptSchemaVersion": "1.0",
                    "callScriptVersion": "1.0",
                    "candidateDataPointSchemas": {
                        "issue_type": {
                            "key": "issue_type",
                            "description": "Type of technical issue",
                            "outputSchema": {
                                "type": "string",
                                "description": "Type of technical issue",
                            },
                        },
                        "device_type": {
                            "key": "device_type",
                            "description": "Device experiencing the issue",
                            "outputSchema": {
                                "type": "string",
                                "description": "Device experiencing the issue",
                            },
                        },
                    },
                    "context": {
                        "job": {
                            "companyName": "Mock Company",
                            "positionTitle": "Software Engineer",
                        }
                    },
                    "tasks": [
                        {
                            "id": "greeter_task",
                            "type": "greeter",
                            "configuration": {
                                "companyName": "Mock Company",
                                "introduction": "Hello! This is a test screening call.",
                            },
                        },
                        {
                            "id": "data_collection_task",
                            "type": "data_collection",
                            "configuration": {
                                "dataPoints": ["issue_type", "device_type"],
                            },
                        },
                        {
                            "id": "closer_task",
                            "type": "closer",
                            "configuration": {
                                "closingMessage": "Thank you for your time!",
                            },
                        },
                    ],
                }

                logger.info(f"Retrieved config for engagement: {engagement_id}")
                self._send_json_response(200, config)
            else:
                self._send_error(404, f"Engagement {engagement_id} not found")
        else:
            self._send_error(400, "Invalid path")

    def _handle_post_data_point(self):
        """Handle POST /api/engagements/{id}/candidate-data-points"""
        path_parts = self.path.split("/")
        if len(path_parts) >= 4:
            engagement_id = path_parts[-2]

            if engagement_id in MockPurplefishHandler.engagements:
                try:
                    content_length = int(self.headers['Content-Length'])
                    post_data = self.rfile.read(content_length)
                    data = json.loads(post_data)

                    MockPurplefishHandler.engagements[engagement_id]["dataPoints"].append({
                        **data,
                        "timestamp": datetime.now().isoformat(),
                    })

                    logger.info(f"Added data point to engagement: {engagement_id}")
                    self._send_json_response(200, {"success": True})

                except Exception as e:
                    self._send_error(400, str(e))
            else:
                self._send_error(404, f"Engagement {engagement_id} not found")
        else:
            self._send_error(400, "Invalid path")

    def _handle_post_message(self):
        """Handle POST /api/engagements/{id}/messages"""
        path_parts = self.path.split("/")
        if len(path_parts) >= 4:
            engagement_id = path_parts[-2]

            if engagement_id in MockPurplefishHandler.engagements:
                try:
                    content_length = int(self.headers['Content-Length'])
                    post_data = self.rfile.read(content_length)
                    data = json.loads(post_data)

                    MockPurplefishHandler.engagements[engagement_id]["messages"].append({
                        **data,
                        "timestamp": datetime.now().isoformat(),
                    })

                    logger.info(f"Added message to engagement: {engagement_id}")
                    self._send_json_response(200, {"success": True})

                except Exception as e:
                    self._send_error(400, str(e))
            else:
                self._send_error(404, f"Engagement {engagement_id} not found")
        else:
            self._send_error(400, "Invalid path")

    def _handle_health_check(self):
        """Handle GET /health"""
        self._send_json_response(200, {
            "status": "ok",
            "service": "mock-purplefish-api",
            "engagements_count": len(MockPurplefishHandler.engagements),
        })

    def _send_json_response(self, code: int, data: Any):
        """Send JSON response"""
        self.send_response(code)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())

    def _send_error(self, code: int, message: str):
        """Send error response"""
        self.send_response(code)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps({"error": message}).encode())

    def log_message(self, format, *args):
        """Override to use custom logging"""
        logger.debug(f"{self.address_string()} - {format % args}")


def run_server(host: str = "127.0.0.1", port: int = 8000):
    """Run the mock Purplefish server"""
    server_address = (host, port)
    httpd = HTTPServer(server_address, MockPurplefishHandler)

    print(f"\n{'='*60}")
    print(f"Mock Purplefish API Server")
    print(f"{'='*60}")
    print(f"Server running at http://{host}:{port}")
    print(f"\nAvailable endpoints:")
    print(f"  POST /api/engagements                              - Create engagement")
    print(f"  GET  /api/engagements/{{id}}/agent-config           - Get agent config")
    print(f"  POST /api/engagements/{{id}}/candidate-data-points  - Post data point")
    print(f"  POST /api/engagements/{{id}}/messages               - Post message")
    print(f"  GET  /health                                       - Health check")
    print(f"\nPress Ctrl+C to stop...")
    print(f"{'='*60}\n")

    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print("\n\nShutting down server...")
        httpd.shutdown()
        print("Server stopped.")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Mock Purplefish API Server")
    parser.add_argument(
        "--host",
        default="127.0.0.1",
        help="Host to bind to (default: 127.0.0.1, use 0.0.0.0 for all interfaces)",
    )
    parser.add_argument(
        "--port",
        type=int,
        default=8000,
        help="Port to bind to (default: 8000)",
    )
    args = parser.parse_args()

    run_server(host=args.host, port=args.port)

